<?php
namespace App\Http\Controllers; use PDO;
final class CrudController{public static function customers(PDO $db):array{if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')==='create_customer'){$s=$db->prepare('INSERT INTO customers(name,notes,created_at) VALUES(?,?,NOW())');$s->execute([trim($_POST['name']),trim($_POST['notes']??'')]);}return ['rows'=>$db->query('SELECT * FROM customers ORDER BY id DESC LIMIT 100')->fetchAll()];}public static function products(PDO $db):array{if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')==='create_product'){$s=$db->prepare("INSERT INTO products(name,price,status,created_at) VALUES(?,?,'active',NOW())");$s->execute([trim($_POST['name']),$_POST['price']]);}return ['rows'=>$db->query('SELECT * FROM products ORDER BY id DESC LIMIT 100')->fetchAll()];}public static function orders(PDO $db):array{if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')==='create_order'){$db->beginTransaction();try{$no='R'.date('ymdHis').random_int(10,99);$s=$db->prepare("INSERT INTO orders(order_no,order_type,status,total_amount,created_at) VALUES(?,?, 'confirmed',?,NOW())");$s->execute([$no,$_POST['order_type'],$_POST['total']]);$db->commit();}catch(\Throwable $e){$db->rollBack();throw $e;}}return ['rows'=>$db->query('SELECT * FROM orders ORDER BY id DESC LIMIT 100')->fetchAll()];}}
